	@ParameterizedTest
	@CsvSource({ "0,false", "1,false", "0,true", "1,true" })
	void conditionalPathsRetainTheirReservedWorkAfterGeneralRefinementRefuses(long minimum, boolean reverse,
			@TempDir Path directory) {
		double[] baseline = new double[3];
		for (int unrelated : new int[] { 1, 3, 2 }) {
			withSession(directory.resolve("unrelated-" + unrelated), minimum, reverse, unrelated,
					(call, session, view, ids, filterId, unrelatedId) -> {
						exhaustGeneralRefinement(call, session, view, ids);
						for (int repeat = 0; repeat < 2; repeat++) {
							PackedCostEstimate estimate = pathEstimate(call, session, ids[1], ids[3], unrelatedId,
									unrelated);
							assertEquals("frontier-v2-omni-path-subgraph", estimate.estimateSource(),
									"conditional path work retains its existing reserve after general refinement refuses");
							assertEquals(2.0d, estimate.invocations(), 0.0d);
							assertTrue(estimate.hasContextualOutputRows());
							assertTrue(estimate.hasComponentOutputRows());
							assertTrue(estimate.workRows() > estimate.outputRows());
							if (unrelated == 1 && repeat == 0) {
								baseline[0] = estimate.outputRows();
								baseline[1] = estimate.workRows();
								baseline[2] = estimate.pathExpansions();
							} else {
								assertEquals(baseline[0], estimate.outputRows(), 0.0d);
								assertEquals(baseline[1], estimate.workRows(), 0.0d);
								assertEquals(baseline[2], estimate.pathExpansions(), 0.0d);
							}
						}
						verify(view, times(statementPatterns(call) + 1)).estimateJoin(any());
						verify(view, times(3)).estimateSubgraph(any());
					});
		}
	}

	@Test
	void pathsAndSemiAntiShareTheSameFiniteReserveAndRepeatedDeclinesDoNotRetry(@TempDir Path directory) {
		withSession(directory, 1L, false, 1, (call, session, view, ids, filterId, unrelatedId) -> {
			PackedCostEstimate prefix = exhaustGeneralRefinement(call, session, view, ids);
			PackedCostEstimate exists = new PackedCostEstimate();
			exists.setContextualRows(2.0d, 2.0d);
			session.refineOperator(filterId, call.operatorContext(2.0d, Double.NaN, prefix.evidenceStateId(), 0),
					exists);
			assertEquals("mapped-omni-correlated-semi-join",
					exists.plannedStringMetric("plannedSemiAntiSelectivitySource"),
					"the actual correlated EXISTS must consume the same mapped reserve");
			PackedCostEstimate first = pathEstimate(call, session, ids[1], ids[3], unrelatedId, 1);
			assertEquals("frontier-v2-omni-path-subgraph", first.estimateSource());
			for (int repeat = 0; repeat < 3; repeat++) {
				PackedCostEstimate refused = pathEstimate(call, session, ids[0], ids[2], unrelatedId, 1);
				assertEquals("lmdb-property-path", refused.estimateSource(),
						"a different path program declines after both existing work channels are exhausted");
				assertFalse(refused.evidenceGuarantee() == EvidenceGuarantee.DATABASE_EXACT);
			}
			verify(view, times(statementPatterns(call) + 1)).estimateJoin(any());
			verify(view, times(3)).estimateSubgraph(any());
		});
	}

